/**
 * The House — how Twyne names and stacks the context around a piece.
 *
 *   House        the writer: default dossier fields and the house charter
 *   Collection   a series of folios sharing a dossier layer and a charter
 *   Folio        one piece, with its own dossier (a `ProjectBrief`)
 *   Charter      standards that follow the writer from piece to piece
 *   Edition      a filed version of a dossier (see `brief-history.ts`)
 *   Amendment    a dossier change the draft itself proposed, once filed
 *   Ledger       every context change: what, when, from where, and why
 *
 * The context stack is the merge of those layers for one folio, each field
 * stamped with the layer it came from. It is exactly what models are handed,
 * so the inspector can show the writer the same thing the models read.
 *
 * Pure: storage lives in `house-store.ts`, sync in `house-sync.ts`.
 */
import type {
  DossierAttachment,
  ProjectBrief,
  ProjectInterviewAnswers,
} from "../types";

export type DossierField = keyof ProjectInterviewAnswers;

export const DOSSIER_FIELDS: readonly DossierField[] = [
  "workingTitle",
  "format",
  "audience",
  "goal",
  "tone",
  "constraints",
  "successSignal",
];

export const DOSSIER_FIELD_LABELS: Record<DossierField, string> = {
  workingTitle: "Working title",
  format: "Form",
  audience: "Reader",
  goal: "Aim",
  tone: "Tone",
  constraints: "Constraints",
  successSignal: "Success looks like",
};

/** Fields a House or Collection may sensibly set for every piece under it. */
export const INHERITABLE_FIELDS: readonly DossierField[] = [
  "format",
  "audience",
  "goal",
  "tone",
  "constraints",
  "successSignal",
];

export type ContextLayer = "house" | "collection" | "folio" | "amendment";

export const LAYER_LABELS: Record<ContextLayer, string> = {
  house: "The House",
  collection: "Collection",
  folio: "Folio dossier",
  amendment: "Amendment",
};

export interface House {
  /** What the house is called on its letterhead; defaults to the writer. */
  name: string;
  dossier: Partial<ProjectInterviewAnswers>;
  updatedAt: number;
}

export interface Collection {
  id: string;
  name: string;
  /** One line on what binds the series together. */
  description: string;
  folioIds: string[];
  dossier: Partial<ProjectInterviewAnswers>;
  createdAt: number;
  updatedAt: number;
}

export type CharterScope = "house" | "collection" | "folio";
export type CharterSeverity = "must" | "prefer";
export type CharterKind = "length" | "citation" | "style" | "voice" | "other";

export interface CharterItem {
  id: string;
  scope: CharterScope;
  /** "house", a collection id, or a folio id, matching `scope`. */
  ownerRef: string;
  text: string;
  severity: CharterSeverity;
  kind: CharterKind;
  order: number;
  updatedAt: number;
}

export type LedgerSource =
  | "interview"
  | "refine"
  | "amendment"
  | "house"
  | "collection"
  | "charter"
  | "manual"
  | "sync";

export const LEDGER_SOURCE_LABELS: Record<LedgerSource, string> = {
  interview: "Filed at the interview",
  refine: "Refined by hand",
  amendment: "Amended from the draft",
  house: "Set at the House",
  collection: "Set for the collection",
  charter: "Charter changed",
  manual: "Edited",
  sync: "Arrived from another device",
};

export interface LedgerEntry {
  id: string;
  at: number;
  layer: ContextLayer | "charter";
  /** "house", a collection id, or a folio id. */
  ownerRef: string;
  field?: string;
  from?: string;
  to?: string;
  source: LedgerSource;
  reason?: string;
}

export interface HouseState {
  house: House;
  collections: Collection[];
  charter: CharterItem[];
  /** Newest first. */
  ledger: LedgerEntry[];
}

export function emptyHouseState(now = 0): HouseState {
  return {
    house: { name: "", dossier: {}, updatedAt: now },
    collections: [],
    charter: [],
    ledger: [],
  };
}

/* ── The stack ─────────────────────────────────────────────────── */

export interface StackField {
  field: DossierField;
  value: string;
  /** Where `value` came from; null when no layer set it. */
  layer: ContextLayer | null;
  /** Lower layers this one overrides, nearest first. */
  shadowed: Array<{ layer: ContextLayer; value: string }>;
}

export interface StackCharterItem extends CharterItem {
  /** True when it comes from the House or the Collection, not this folio. */
  inherited: boolean;
}

export interface ContextStack {
  folioId: string;
  house: House;
  collection: Collection | null;
  fields: Record<DossierField, StackField>;
  charter: StackCharterItem[];
  attachments: DossierAttachment[];
  /** Filed amendments for this folio, newest first. */
  amendments: LedgerEntry[];
}

export function collectionForFolio(
  state: HouseState,
  folioId: string | null | undefined,
): Collection | null {
  if (!folioId) return null;
  return state.collections.find((c) => c.folioIds.includes(folioId)) ?? null;
}

const clean = (value: string | undefined) => (value ?? "").trim();

/**
 * Merge House → Collection → Folio. The nearest layer that says something
 * wins; the ones it overrides stay visible as `shadowed`, so the inspector
 * can show a collection's tone being overruled by one piece.
 */
export function assembleContextStack(
  state: HouseState,
  folioId: string,
  brief: ProjectBrief | null,
): ContextStack {
  const collection = collectionForFolio(state, folioId);
  const amendments = state.ledger.filter(
    (entry) => entry.source === "amendment" && entry.ownerRef === folioId,
  );
  const amended = new Set(amendments.map((entry) => entry.field));

  const fields = {} as Record<DossierField, StackField>;
  for (const field of DOSSIER_FIELDS) {
    const candidates: Array<{ layer: ContextLayer; value: string }> = [];
    const folioValue = clean(brief?.answers[field]);
    if (folioValue)
      candidates.push({
        layer: amended.has(field) ? "amendment" : "folio",
        value: folioValue,
      });
    if (INHERITABLE_FIELDS.includes(field)) {
      const collectionValue = clean(collection?.dossier[field]);
      if (collectionValue)
        candidates.push({ layer: "collection", value: collectionValue });
      const houseValue = clean(state.house.dossier[field]);
      if (houseValue) candidates.push({ layer: "house", value: houseValue });
    }
    const [top, ...rest] = candidates;
    fields[field] = {
      field,
      value: top?.value ?? "",
      layer: top?.layer ?? null,
      shadowed: rest,
    };
  }

  const owners = new Set(["house", folioId, ...(collection ? [collection.id] : [])]);
  const charter = state.charter
    .filter((item) => owners.has(item.ownerRef))
    .map((item) => ({ ...item, inherited: item.ownerRef !== folioId }))
    .sort(
      (a, b) =>
        scopeRank(a.scope) - scopeRank(b.scope) ||
        severityRank(a.severity) - severityRank(b.severity) ||
        a.order - b.order,
    );

  return {
    folioId,
    house: state.house,
    collection,
    fields,
    charter,
    attachments: brief?.attachments ?? [],
    amendments,
  };
}

function scopeRank(scope: CharterScope): number {
  return scope === "house" ? 0 : scope === "collection" ? 1 : 2;
}

function severityRank(severity: CharterSeverity): number {
  return severity === "must" ? 0 : 1;
}

/**
 * The merged view as a `ProjectBrief`, for read-only consumers that already
 * take one. The house and collection charters join the constraints so every
 * existing prompt builder carries them without changing shape.
 */
export function effectiveBrief(
  stack: ContextStack,
  brief: ProjectBrief | null,
): ProjectBrief {
  const answers = Object.fromEntries(
    DOSSIER_FIELDS.map((field) => [field, stack.fields[field].value]),
  ) as unknown as ProjectInterviewAnswers;
  const standards = stack.charter.map(
    (item) => `${item.severity === "must" ? "Must" : "Prefer"}: ${item.text}`,
  );
  if (standards.length) {
    answers.constraints = [answers.constraints, ...standards]
      .filter(Boolean)
      .join("\n");
  }
  const now = Date.now();
  return {
    answers,
    attachments: stack.attachments,
    ...(brief?.probes?.length ? { probes: brief.probes } : {}),
    completedAt: brief?.completedAt ?? now,
    updatedAt: brief?.updatedAt ?? now,
  };
}

/** A rough, provider-neutral token estimate: four characters a token. */
export function estimateTokens(text: string): number {
  return Math.ceil(text.length / 4);
}

export interface ModelContext {
  text: string;
  layers: Array<{ layer: ContextLayer | "charter"; chars: number; tokens: number }>;
}

/** The exact block a model is handed, with a per-layer cost breakdown. */
export function contextForModels(stack: ContextStack): ModelContext {
  const byLayer = new Map<ContextLayer | "charter", number>();
  const lines: string[] = [];
  for (const field of DOSSIER_FIELDS) {
    const entry = stack.fields[field];
    if (!entry.value || !entry.layer) continue;
    const line = `${DOSSIER_FIELD_LABELS[field]}: ${entry.value}`;
    lines.push(line);
    byLayer.set(entry.layer, (byLayer.get(entry.layer) ?? 0) + line.length);
  }
  if (stack.charter.length) {
    lines.push("Charter:");
    for (const item of stack.charter) {
      const line = `- ${item.severity === "must" ? "Must" : "Prefer"}: ${item.text}`;
      lines.push(line);
      byLayer.set("charter", (byLayer.get("charter") ?? 0) + line.length);
    }
  }
  const text = lines.join("\n");
  return {
    text,
    layers: [...byLayer].map(([layer, chars]) => ({
      layer,
      chars,
      tokens: Math.ceil(chars / 4),
    })),
  };
}

/** Ledger entries worth one row each: what changed about a folio's context. */
export function ledgerForFolio(
  state: HouseState,
  folioId: string,
): LedgerEntry[] {
  const collection = collectionForFolio(state, folioId);
  const owners = new Set(["house", folioId, ...(collection ? [collection.id] : [])]);
  return state.ledger.filter((entry) => owners.has(entry.ownerRef));
}
/**
 * The House, stored on this device. One `meta` record holds the whole
 * `HouseState`; every write is read back, because the IDB helper absorbs
 * storage failures and a Qwik store proxy fails structured clone silently.
 *
 * Changes fire `HOUSE_CHANGED_EVENT` with the new state; `house-sync.ts`
 * listens to push them to Convex, and the inspector and editor listen to
 * redraw. Remote pulls write through `replaceHouseState(…, { remote: true })`
 * so they do not bounce straight back out.
 */
import { loadMetaFromIdb, saveMetaToIdb, toStorable } from "./idb";
import {
  emptyHouseState,
  type CharterItem,
  type Collection,
  type DossierField,
  type HouseState,
  type LedgerEntry,
} from "./house-model";

export const HOUSE_META_KEY = "house-state";
export const HOUSE_CHANGED_EVENT = "twyne:house-changed";
const MAX_LOCAL_LEDGER = 500;

export interface HouseChangedDetail {
  state: HouseState;
  /** True when the change arrived from sync rather than the writer. */
  remote: boolean;
}

function normalize(value: unknown): HouseState {
  const base = emptyHouseState();
  if (!value || typeof value !== "object") return base;
  const raw = value as Partial<HouseState>;
  return {
    house: {
      name: typeof raw.house?.name === "string" ? raw.house.name : "",
      dossier:
        raw.house?.dossier && typeof raw.house.dossier === "object"
          ? raw.house.dossier
          : {},
      updatedAt:
        typeof raw.house?.updatedAt === "number" ? raw.house.updatedAt : 0,
    },
    collections: Array.isArray(raw.collections) ? raw.collections : [],
    charter: Array.isArray(raw.charter) ? raw.charter : [],
    ledger: Array.isArray(raw.ledger) ? raw.ledger : [],
  };
}

export async function loadHouseState(): Promise<HouseState> {
  if (typeof window === "undefined") return emptyHouseState();
  return normalize(await loadMetaFromIdb<HouseState>(HOUSE_META_KEY));
}

export async function replaceHouseState(
  next: HouseState,
  options: { remote?: boolean } = {},
): Promise<HouseState> {
  const state = toStorable({
    ...next,
    ledger: next.ledger.slice(0, MAX_LOCAL_LEDGER),
  });
  await saveMetaToIdb(HOUSE_META_KEY, state);
  const saved = await loadMetaFromIdb<HouseState>(HOUSE_META_KEY);
  if (JSON.stringify(saved) !== JSON.stringify(state)) {
    throw new Error("The House could not be saved on this device.");
  }
  window.dispatchEvent(
    new CustomEvent<HouseChangedDetail>(HOUSE_CHANGED_EVENT, {
      detail: { state, remote: options.remote === true },
    }),
  );
  return state;
}

/** Load, apply `change`, save — the one path every edit below takes. */
async function update(
  change: (state: HouseState, now: number) => HouseState,
): Promise<HouseState> {
  const now = Date.now();
  return replaceHouseState(change(await loadHouseState(), now));
}

export function ledgerEntry(
  entry: Omit<LedgerEntry, "id" | "at">,
  now = Date.now(),
): LedgerEntry {
  return { id: crypto.randomUUID(), at: now, ...entry };
}

export function appendLedger(
  entries: Array<Omit<LedgerEntry, "id" | "at">>,
): Promise<HouseState> {
  return update((state, now) => ({
    ...state,
    ledger: [...entries.map((e) => ledgerEntry(e, now)), ...state.ledger],
  }));
}

export function setHouseName(name: string): Promise<HouseState> {
  return update((state, now) => ({
    ...state,
    house: { ...state.house, name: name.trim(), updatedAt: now },
  }));
}

export function setHouseField(
  field: DossierField,
  value: string,
): Promise<HouseState> {
  return update((state, now) => {
    const from = state.house.dossier[field] ?? "";
    if (from === value.trim()) return state;
    return {
      ...state,
      house: {
        ...state.house,
        dossier: { ...state.house.dossier, [field]: value.trim() },
        updatedAt: now,
      },
      ledger: [
        ledgerEntry(
          {
            layer: "house",
            ownerRef: "house",
            field,
            from,
            to: value.trim(),
            source: "house",
          },
          now,
        ),
        ...state.ledger,
      ],
    };
  });
}

export function createCollection(
  name: string,
  folioIds: string[] = [],
): Promise<HouseState> {
  return update((state, now) => {
    const collection: Collection = {
      id: crypto.randomUUID(),
      name: name.trim() || "Untitled collection",
      description: "",
      // A folio belongs to at most one collection.
      folioIds,
      dossier: {},
      createdAt: now,
      updatedAt: now,
    };
    return {
      ...state,
      collections: [
        ...state.collections.map((c) => ({
          ...c,
          folioIds: c.folioIds.filter((id) => !folioIds.includes(id)),
        })),
        collection,
      ],
      ledger: [
        ledgerEntry(
          {
            layer: "collection",
            ownerRef: collection.id,
            to: collection.name,
            source: "collection",
            reason: "Collection founded",
          },
          now,
        ),
        ...state.ledger,
      ],
    };
  });
}

export function updateCollection(
  id: string,
  patch: Partial<Pick<Collection, "name" | "description">> & {
    field?: { name: DossierField; value: string };
  },
): Promise<HouseState> {
  return update((state, now) => {
    const ledger: LedgerEntry[] = [];
    const collections = state.collections.map((c) => {
      if (c.id !== id) return c;
      const next = { ...c, updatedAt: now };
      if (patch.name !== undefined) next.name = patch.name.trim() || c.name;
      if (patch.description !== undefined)
        next.description = patch.description.trim();
      if (patch.field) {
        const from = c.dossier[patch.field.name] ?? "";
        const to = patch.field.value.trim();
        if (from !== to) {
          next.dossier = { ...c.dossier, [patch.field.name]: to };
          ledger.push(
            ledgerEntry(
              {
                layer: "collection",
                ownerRef: id,
                field: patch.field.name,
                from,
                to,
                source: "collection",
              },
              now,
            ),
          );
        }
      }
      return next;
    });
    return { ...state, collections, ledger: [...ledger, ...state.ledger] };
  });
}

export function deleteCollection(id: string): Promise<HouseState> {
  return update((state) => ({
    ...state,
    collections: state.collections.filter((c) => c.id !== id),
    charter: state.charter.filter((item) => item.ownerRef !== id),
  }));
}

/** File a folio under a collection, or take it out with `null`. */
export function setFolioCollection(
  folioId: string,
  collectionId: string | null,
): Promise<HouseState> {
  return update((state, now) => ({
    ...state,
    collections: state.collections.map((c) => {
      const has = c.folioIds.includes(folioId);
      if (c.id === collectionId && !has)
        return { ...c, folioIds: [...c.folioIds, folioId], updatedAt: now };
      if (c.id !== collectionId && has)
        return {
          ...c,
          folioIds: c.folioIds.filter((f) => f !== folioId),
          updatedAt: now,
        };
      return c;
    }),
  }));
}

export function upsertCharterItem(
  item: Omit<CharterItem, "id" | "order" | "updatedAt"> &
    Partial<Pick<CharterItem, "id" | "order">>,
): Promise<HouseState> {
  return update((state, now) => {
    const existing = item.id
      ? state.charter.find((c) => c.id === item.id)
      : undefined;
    const siblings = state.charter.filter((c) => c.ownerRef === item.ownerRef);
    const next: CharterItem = {
      ...item,
      text: item.text.trim(),
      id: item.id ?? crypto.randomUUID(),
      order: item.order ?? existing?.order ?? siblings.length,
      updatedAt: now,
    };
    return {
      ...state,
      charter: existing
        ? state.charter.map((c) => (c.id === next.id ? next : c))
        : [...state.charter, next],
      ledger: [
        ledgerEntry(
          {
            layer: "charter",
            ownerRef: item.ownerRef,
            field: next.severity,
            from: existing?.text,
            to: next.text,
            source: "charter",
          },
          now,
        ),
        ...state.ledger,
      ],
    };
  });
}

export function removeCharterItem(id: string): Promise<HouseState> {
  return update((state, now) => {
    const item = state.charter.find((c) => c.id === id);
    if (!item) return state;
    return {
      ...state,
      charter: state.charter.filter((c) => c.id !== id),
      ledger: [
        ledgerEntry(
          {
            layer: "charter",
            ownerRef: item.ownerRef,
            from: item.text,
            source: "charter",
            reason: "Standard withdrawn",
          },
          now,
        ),
        ...state.ledger,
      ],
    };
  });
}
import type { ProjectBrief } from "../types";
import { loadMetaFromIdb, saveMetaToIdb } from "./idb";

export interface BriefEdition {
  id: string;
  savedAt: number;
  brief: ProjectBrief;
}

const MAX_BRIEF_EDITIONS = 20;

function editionsKey(folioId: string): string {
  return `brief-editions:${folioId}`;
}

export async function loadBriefEditions(
  folioId: string | null | undefined,
): Promise<BriefEdition[]> {
  if (!folioId) return [];
  const editions = await loadMetaFromIdb<BriefEdition[]>(editionsKey(folioId));
  if (!Array.isArray(editions)) return [];
  return editions
    .filter(
      (edition) =>
        edition &&
        typeof edition.id === "string" &&
        typeof edition.savedAt === "number" &&
        edition.brief?.answers,
    )
    .sort((a, b) => b.savedAt - a.savedAt)
    .slice(0, MAX_BRIEF_EDITIONS);
}

/** Keep each superseded brief available for inspection, without changing the
 * active brief or the manuscript's separate revision history. */
export async function archiveBriefEdition(
  folioId: string,
  brief: ProjectBrief,
): Promise<void> {
  if (!folioId) return;
  const editions = await loadBriefEditions(folioId);
  const latest = editions[0];
  if (latest && JSON.stringify(latest.brief) === JSON.stringify(brief)) {
    return;
  }
  const edition: BriefEdition = {
    id: `${brief.updatedAt}-${crypto.randomUUID()}`,
    savedAt: brief.updatedAt || Date.now(),
    brief,
  };
  await saveMetaToIdb(
    editionsKey(folioId),
    [edition, ...editions].slice(0, MAX_BRIEF_EDITIONS),
  );
}
/**
 * Writer-authored inline comments. The CommentMark in the manuscript
 * holds the id; the body, replies, and resolve state live in these
 * tables. Mirrors `personaNotes`/`personaReplies` but for human
 * comments — kept as a separate table so the data model is clean
 * (user comments are not editorial feedback, even when the UI looks
 * the same).
 *
 * All mutations are auth-gated to the calling user. No userId
 * arguments — the Convex auth guideline is non-negotiable.
 */

import { mutation, query } from "./_generated/server";
import { v } from "convex/values";

/* ── Comments ──────────────────────────────────────────────────── */

export const addComment = mutation({
  args: {
    commentId: v.string(),
    folioId: v.string(),
    text: v.string(),
    author: v.string(),
    anchor: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Not signed in");
    const ownerId = identity.tokenIdentifier;

    const now = Date.now();
    return await ctx.db.insert("userComments", {
      ownerId,
      commentId: args.commentId,
      folioId: args.folioId,
      text: args.text,
      author: args.author,
      anchor: args.anchor,
      resolved: false,
      createdAt: now,
      updatedAt: now,
    });
  },
});

export const updateCommentText = mutation({
  args: {
    commentId: v.string(),
    text: v.string(),
  },
  handler: async (ctx, { commentId, text }) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Not signed in");
    const ownerId = identity.tokenIdentifier;
    const row = await ctx.db
      .query("userComments")
      .withIndex("by_ownerId_commentId", (q) =>
        q.eq("ownerId", ownerId).eq("commentId", commentId),
      )
      .first();
    if (!row) throw new Error("Comment not found");
    await ctx.db.patch(row._id, { text, updatedAt: Date.now() });
  },
});

export const resolveComment = mutation({
  args: { commentId: v.string() },
  handler: async (ctx, { commentId }) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Not signed in");
    const ownerId = identity.tokenIdentifier;
    const row = await ctx.db
      .query("userComments")
      .withIndex("by_ownerId_commentId", (q) =>
        q.eq("ownerId", ownerId).eq("commentId", commentId),
      )
      .first();
    if (!row) return;
    await ctx.db.patch(row._id, {
      resolved: !row.resolved,
      updatedAt: Date.now(),
    });
  },
});

/** Set resolution state idempotently so offline/local reconciliation converges. */
export const setCommentResolved = mutation({
  args: { commentId: v.string(), resolved: v.boolean() },
  returns: v.null(),
  handler: async (ctx, { commentId, resolved }) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Not signed in");
    const ownerId = identity.tokenIdentifier;
    const row = await ctx.db
      .query("userComments")
      .withIndex("by_ownerId_commentId", (q) =>
        q.eq("ownerId", ownerId).eq("commentId", commentId),
      )
      .first();
    if (!row || row.resolved === resolved) return null;
    await ctx.db.patch(row._id, {
      resolved,
      updatedAt: Date.now(),
    });
    return null;
  },
});

export const deleteComment = mutation({
  args: { commentId: v.string() },
  handler: async (ctx, { commentId }) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Not signed in");
    const ownerId = identity.tokenIdentifier;
    const row = await ctx.db
      .query("userComments")
      .withIndex("by_ownerId_commentId", (q) =>
        q.eq("ownerId", ownerId).eq("commentId", commentId),
      )
      .first();
    if (!row) return;
    await ctx.db.delete(row._id);
    // Cascade: remove replies too.
    const replies = await ctx.db
      .query("userCommentReplies")
      .withIndex("by_ownerId_commentId", (q) =>
        q.eq("ownerId", ownerId).eq("commentId", commentId),
      )
      .collect();
    for (const r of replies) {
      await ctx.db.delete(r._id);
    }
  },
});

export const listComments = query({
  args: { folioId: v.optional(v.string()) },
  handler: async (ctx, { folioId }) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) return [];
    const ownerId = identity.tokenIdentifier;
    const all = await ctx.db
      .query("userComments")
      .withIndex("by_ownerId", (q) => q.eq("ownerId", ownerId))
      .collect();
    return all
      .filter((c) => !folioId || c.folioId === folioId)
      .sort((a, b) => a.createdAt - b.createdAt)
      .map((c) => ({
        commentId: c.commentId,
        folioId: c.folioId,
        text: c.text,
        author: c.author,
        anchor: c.anchor,
        resolved: c.resolved,
        createdAt: c.createdAt,
        updatedAt: c.updatedAt,
      }));
  },
});

/* ── Replies ──────────────────────────────────────────────────── */

export const addReply = mutation({
  args: {
    replyId: v.string(),
    commentId: v.string(),
    author: v.string(),
    text: v.string(),
  },
  handler: async (ctx, args) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Not signed in");
    const ownerId = identity.tokenIdentifier;
    return await ctx.db.insert("userCommentReplies", {
      ownerId,
      replyId: args.replyId,
      commentId: args.commentId,
      author: args.author,
      text: args.text,
      createdAt: Date.now(),
    });
  },
});

export const listReplies = query({
  args: { commentId: v.optional(v.string()) },
  handler: async (ctx, { commentId }) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) return [];
    const ownerId = identity.tokenIdentifier;
    if (commentId) {
      const rows = await ctx.db
        .query("userCommentReplies")
        .withIndex("by_ownerId_commentId", (q) =>
          q.eq("ownerId", ownerId).eq("commentId", commentId),
        )
        .collect();
      return rows.sort((a, b) => a.createdAt - b.createdAt);
    }
    const rows = await ctx.db
      .query("userCommentReplies")
      .withIndex("by_ownerId", (q) => q.eq("ownerId", ownerId))
      .collect();
    return rows.sort((a, b) => a.createdAt - b.createdAt);
  },
});

export const deleteReply = mutation({
  args: { replyId: v.string() },
  handler: async (ctx, { replyId }) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Not signed in");
    const ownerId = identity.tokenIdentifier;
    const rows = await ctx.db
      .query("userCommentReplies")
      .withIndex("by_ownerId", (q) => q.eq("ownerId", ownerId))
      .collect();
    const target = rows.find((r) => r.replyId === replyId);
    if (target) {
      await ctx.db.delete(target._id);
    }
  },
});
