        ...state.ledger,
      ],
    };
  });
}

export function createCollection(
  name: string,
  folioIds: string[] = [],
): Promise<HouseState> {
  return update((state, now) => {
    const collection: Collection = {
      id: crypto.randomUUID(),
      name: name.trim() || "Untitled collection",
      description: "",
      // A folio belongs to at most one collection.
      folioIds,
      dossier: {},
      createdAt: now,
      updatedAt: now,
    };
