import type { ProjectBrief } from "../types";
import { loadMetaFromIdb, saveMetaToIdb } from "./idb";

export interface BriefEdition {
  id: string;
  savedAt: number;
  brief: ProjectBrief;
}

const MAX_BRIEF_EDITIONS = 20;

function editionsKey(folioId: string): string {
  return `brief-editions:${folioId}`;
}

export async function loadBriefEditions(
  folioId: string | null | undefined,
): Promise<BriefEdition[]> {
  if (!folioId) return [];
  const editions = await loadMetaFromIdb<BriefEdition[]>(editionsKey(folioId));
  if (!Array.isArray(editions)) return [];
  return editions
    .filter(
      (edition) =>
        edition &&
        typeof edition.id === "string" &&
        typeof edition.savedAt === "number" &&
        edition.brief?.answers,
    )
    .sort((a, b) => b.savedAt - a.savedAt)
    .slice(0, MAX_BRIEF_EDITIONS);
}

/** Keep each superseded brief available for inspection, without changing the
 * active brief or the manuscript's separate revision history. */
export async function archiveBriefEdition(
  folioId: string,
  brief: ProjectBrief,
): Promise<void> {
  if (!folioId) return;
  const editions = await loadBriefEditions(folioId);
  const latest = editions[0];
  if (latest && JSON.stringify(latest.brief) === JSON.stringify(brief)) {
    return;
  }
  const edition: BriefEdition = {
    id: `${brief.updatedAt}-${crypto.randomUUID()}`,
    savedAt: brief.updatedAt || Date.now(),
    brief,
  };
  await saveMetaToIdb(
    editionsKey(folioId),
    [edition, ...editions].slice(0, MAX_BRIEF_EDITIONS),
  );
}
/// <reference types="vite/client" />

import { convexTest } from "convex-test";
import { describe, expect, test } from "vitest";
import { api } from "./_generated/api";
import schema from "./schema";

const supportsViteModules = typeof import.meta.glob === "function";
const modules = supportsViteModules ? import.meta.glob("./**/*.ts") : {};
const describeConvex = supportsViteModules ? describe : describe.skip;

describeConvex("user comment resolution", () => {
  test("sets the requested state idempotently", async () => {
    const t = convexTest(schema, modules);
    const writer = t.withIdentity({
      tokenIdentifier: "test-issuer|comment-writer",
    });

    await writer.mutation(api.userComments.addComment, {
      commentId: "comment-1",
      folioId: "folio-1",
      text: "Keep this thread synchronized.",
      author: "Writer",
    });

    await writer.mutation(api.userComments.setCommentResolved, {
      commentId: "comment-1",
      resolved: true,
    });
    await writer.mutation(api.userComments.setCommentResolved, {
      commentId: "comment-1",
      resolved: true,
    });
    expect(
      (await writer.query(api.userComments.listComments, {}))[0]?.resolved,
    ).toBe(true);

    await writer.mutation(api.userComments.setCommentResolved, {
      commentId: "comment-1",
      resolved: false,
    });
    await writer.mutation(api.userComments.setCommentResolved, {
      commentId: "comment-1",
      resolved: false,
    });
    expect(
      (await writer.query(api.userComments.listComments, {}))[0]?.resolved,
    ).toBe(false);
  });
});
import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    environment: "edge-runtime",
  },
});

